import type { CSSProperties } from 'react';
import { baseIconNames, type BaseIconName } from '../../icons/names';
import './Icon.css';

/* The Figma "Base icons" set (src/icons/base, generated by `npm run icons`). */
const baseFiles = import.meta.glob<string>('../../icons/base/*.svg', { eager: true, query: '?url', import: 'default' });
const urlOf = (name: string) => baseFiles[`../../icons/base/${name}.svg`];

export type IconName = BaseIconName;

/** Every icon name. */
export const iconNames: IconName[] = [...baseIconNames];

/** Kept for stories and Controls: name → file URL. */
export const icons = Object.fromEntries(iconNames.map(n => [n, urlOf(n)])) as Record<IconName, string>;

export type IconProps = {
  name: IconName;
  /** Size in px. The guidelines use 12, 16, 20 and 24, matched to the component and text size. */
  size?: 12 | 16 | 20 | 24;
  className?: string;
};

/**
 * Single-colour icon drawn as a CSS mask, so its colour follows `currentColor`
 * and the parent's token, in both themes. Decorative: the parent carries the accessible name.
 */
export function Icon({ name, size = 20, className = '' }: IconProps) {
  const style = { '--icon-src': `url("${icons[name]}")`, '--icon-size': `${size}px` } as CSSProperties;
  return <span className={`grg-icon ${className}`} style={style} aria-hidden="true" />;
}
